<script>
const BASE=<?=json_encode(BASE_URL)?>, SCHOOL_YEAR=<?=json_encode($year)?>;
const STORE='cdsCardDesignerV2';
const SAMPLE={id:'sample',name:'NGUYỄN VĂN AN',code:'XM25010001',class_name:'10A1',photo_url:'',verify_url:location.origin+BASE+'student_verify.php?id=sample&t=sample'};
const DIMS={vertical:{w:54,h:86},horizontal:{w:90,h:60}};
const text=(id,label,face,x,y,w,h,value,size=8,color='#10243a',weight=700,align='center')=>({id,label,face,type:'text',x,y,w,h,text:value,fontSize:size,color,fontWeight:weight,fontStyle:'normal',underline:false,align,lineHeight:1.15,letterSpacing:0,wrap:true,visible:true,locked:false,z:10});
const image=(id,label,face,type,x,y,w,h,source)=>({id,label,face,type,x,y,w,h,source,visible:true,locked:false,z:10});
function defaultState(){return {type:'vertical',face:'front',colors:{main:'#0d47a1',second:'#42a5f5',accent:'#f4b400'},grid:false,safe:true,objects:[
 image('logo','Logo trường','front','logo',3,3,11,11,''),
 text('agency','Sở GD&ĐT','front',15,3.5,35,4,'SỞ GD&ĐT TUYÊN QUANG',6.5,'#ffffff',700,'left'),
 text('school','Tên trường','front',15,7.5,36,7,'TRƯỜNG PTDTNT THCS&THPT XÍN MẦN',7.2,'#ffffff',900,'left'),
 text('title','Tiêu đề','front',4,19,46,7,'THẺ HỌC SINH',13,'#d71920',900,'center'),
 image('photo','Ảnh học sinh','front','photo',16,28,22,29.3,''),
 text('studentName','Tên học sinh','front',3,59,48,7,'{{student_name}}',9.5,'#0d47a1',900,'center'),
 text('classYear','Lớp – Năm học','front',4,66,46,8,'Lớp: {{class_name}}\nNăm học: {{school_year}}',7.2,'#10243a',600,'center'),
 text('cohort','Niên khóa','front',4,74,46,5,'Niên khóa: 2022 - 2025',7,'#10243a',600,'center'),
 text('studentCode','Mã học sinh','front',4,79,46,4,'Mã HS: {{student_code}}',6.6,'#10243a',600,'center'),
 text('ruleTitle','Tiêu đề quy định','back',5,5,44,7,'QUY ĐỊNH SỬ DỤNG THẺ',9,'#ffffff',900,'center'),
 text('rules','Nội dung quy định','back',4,15,46,45,'1. Học sinh phải mang thẻ khi đến trường.\n2. Không cho người khác mượn thẻ.\n3. Không tẩy xóa hoặc làm hư hỏng thẻ.\n4. Khi mất thẻ phải báo ngay cho nhà trường.\n5. Thẻ chỉ có giá trị trong niên khóa.',6.5,'#10243a',400,'left'),
 image('qr','Mã QR','back','qr',19,61,16,16,''),
 text('qrNote','Ghi chú QR','back',5,78,44,5,'Quét mã để xác minh hoặc mượn sách thư viện.',6,'#10243a',500,'center')
]}}
let state;try{state=Object.assign(defaultState(),JSON.parse(localStorage.getItem(STORE)||'{}'))}catch(e){state=defaultState()}
if(!Array.isArray(state.objects))state=defaultState();
let selectedId=state.objects[0]?.id||null,history=[],future=[],loadedStudents=[],dragInfo=null;
const $=id=>document.getElementById(id), dim=()=>DIMS[state.type], current=()=>state.objects.find(o=>o.id===selectedId), faceObjects=()=>state.objects.filter(o=>o.face===state.face).sort((a,b)=>a.z-b.z);
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function snapshot(){history.push(JSON.stringify(state));if(history.length>80)history.shift();future=[]}
function save(){localStorage.setItem(STORE,JSON.stringify(state));showStatus('Đã lưu mẫu V2.')}
function showStatus(msg){$('sizeInfo').textContent=(state.type==='vertical'?'Dọc ':'Ngang ')+dim().w+' × '+dim().h+' mm · '+msg;setTimeout(()=>{$('sizeInfo').textContent=(state.type==='vertical'?'Dọc ':'Ngang ')+dim().w+' × '+dim().h+' mm'},1600)}
function resolveText(v,s){return String(v||'').replaceAll('{{student_name}}',s.name||'—').replaceAll('{{class_name}}',s.class_name||'—').replaceAll('{{school_year}}',SCHOOL_YEAR).replaceAll('{{student_code}}',s.code||'—')}
function objectStyle(o){return `left:${o.x/dim().w*100}%;top:${o.y/dim().h*100}%;width:${o.w/dim().w*100}%;height:${o.h/dim().h*100}%;z-index:${o.z};${o.visible?'':'display:none;'}${o.type==='text'?`font-size:${o.fontSize}pt;color:${o.color};font-weight:${o.fontWeight};font-style:${o.fontStyle};text-decoration:${o.underline?'underline':'none'};text-align:${o.align};line-height:${o.lineHeight};letter-spacing:${o.letterSpacing}px;white-space:${o.wrap?'pre-wrap':'nowrap'};justify-content:${o.align==='left'?'flex-start':o.align==='right'?'flex-end':'center'};`:''}`}
function objectHtml(o,s,editing){let body='';if(o.type==='text')body=esc(resolveText(o.text,s)).replace(/\n/g,'<br>');else if(o.type==='photo')body=s.photo_url?`<img src="${esc(s.photo_url)}" onerror="this.style.display='none'">`:'<div class="w-100 h-100 d-flex align-items-center justify-content-center bg-light"><i class="bi bi-person fs-2 text-secondary"></i></div>';else if(o.type==='logo')body=o.source?`<img src="${o.source}">`:'<div class="w-100 h-100 d-flex align-items-center justify-content-center text-white"><i class="bi bi-building fs-4"></i></div>';else if(o.type==='qr')body=`<div class="qr-box" data-url="${esc(s.verify_url||'')}"></div>`;
return `<div class="object ${o.type} ${editing&&o.id===selectedId?'selected':''} ${o.locked?'locked':''}" data-id="${o.id}" style="${objectStyle(o)}">${body}${editing?'<span class="resize-handle"></span>':''}</div>`}
function faceHtml(face,s,editing=false,designOnly=false){return `<section class="card-face ${state.type} ${face} ${designOnly?'design-face':''} ${state.grid&&designOnly?'grid-on':''}" data-face="${face}"><div class="decor-top"></div><div class="decor-bottom"></div>${state.objects.filter(o=>o.face===face).sort((a,b)=>a.z-b.z).map(o=>objectHtml(o,s,editing)).join('')}${state.safe&&designOnly?'<div class="safe-line"></div>':''}</section>`}
function makeQr(root){root.querySelectorAll('.qr-box').forEach(el=>{el.innerHTML='';if(window.QRCode)new QRCode(el,{text:el.dataset.url||' ',width:120,height:120,correctLevel:QRCode.CorrectLevel.M})})}
function renderCanvas(){document.documentElement.style.setProperty('--main',state.colors.main);document.documentElement.style.setProperty('--second',state.colors.second);document.documentElement.style.setProperty('--accent',state.colors.accent);$('canvasHost').innerHTML=faceHtml(state.face,SAMPLE,true,true);makeQr($('canvasHost'));bindCanvas();renderLayers();renderProps();document.querySelectorAll('.type-btn').forEach(b=>b.classList.toggle('active',b.dataset.type===state.type));document.querySelectorAll('.face-tabs .btn').forEach(b=>b.classList.toggle('active',b.dataset.face===state.face));$('mainColor').value=state.colors.main;$('secondColor').value=state.colors.second;$('accentColor').value=state.colors.accent}
function renderLayers(){$('layerList').innerHTML=faceObjects().slice().reverse().map(o=>`<div class="layer ${o.id===selectedId?'active':''}" data-id="${o.id}"><button class="mini-btn toggle-visible" title="Ẩn/hiện"><i class="bi ${o.visible?'bi-eye':'bi-eye-slash'}"></i></button><span class="grow">${esc(o.label)}</span><button class="mini-btn toggle-lock"><i class="bi ${o.locked?'bi-lock-fill':'bi-unlock'}"></i></button></div>`).join('')}
function renderProps(){const o=current();$('noSelection').classList.toggle('hidden',!!o);$('propertyForm').classList.toggle('hidden',!o);if(!o)return;$('pLabel').value=o.label;$('pX').value=o.x;$('pY').value=o.y;$('pW').value=o.w;$('pH').value=o.h;$('pVisible').checked=o.visible;$('pLocked').checked=o.locked;const isText=o.type==='text';$('textProps').classList.toggle('hidden',!isText);if(isText){$('pText').value=o.text;$('pFont').value=o.fontSize;$('pColor').value=o.color;$('pWeight').value=o.fontWeight;$('pAlign').value=o.align;$('pLine').value=o.lineHeight;$('pLetter').value=o.letterSpacing;$('pItalic').checked=o.fontStyle==='italic';$('pUnderline').checked=o.underline;$('pWrap').checked=o.wrap}}
function bindCanvas(){$('canvasHost').querySelectorAll('.object').forEach(el=>{el.addEventListener('pointerdown',startDrag);el.querySelector('.resize-handle')?.addEventListener('pointerdown',startResize)})}
function select(id){selectedId=id;renderCanvas()}
function startDrag(e){if(e.target.classList.contains('resize-handle'))return;const o=state.objects.find(x=>x.id===e.currentTarget.dataset.id);selectedId=o.id;if(o.locked){renderCanvas();return}snapshot();e.preventDefault();const face=e.currentTarget.closest('.card-face'),r=face.getBoundingClientRect(),sx=e.clientX,sy=e.clientY,ox=o.x,oy=o.y,d=dim();dragInfo={};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.onpointermove=v=>{o.x=Math.max(0,Math.min(d.w-o.w,ox+(v.clientX-sx)/r.width*d.w));o.y=Math.max(0,Math.min(d.h-o.h,oy+(v.clientY-sy)/r.height*d.h));e.currentTarget.style.left=o.x/d.w*100+'%';e.currentTarget.style.top=o.y/d.h*100+'%';renderProps()};e.currentTarget.onpointerup=()=>{e.currentTarget.onpointermove=null;renderCanvas()}}
function startResize(e){e.stopPropagation();const el=e.currentTarget.parentElement,o=state.objects.find(x=>x.id===el.dataset.id);if(o.locked)return;snapshot();e.preventDefault();const face=el.closest('.card-face'),r=face.getBoundingClientRect(),sx=e.clientX,sy=e.clientY,ow=o.w,oh=o.h,d=dim();el.setPointerCapture(e.pointerId);el.onpointermove=v=>{o.w=Math.max(1,Math.min(d.w-o.x,ow+(v.clientX-sx)/r.width*d.w));o.h=Math.max(1,Math.min(d.h-o.y,oh+(v.clientY-sy)/r.height*d.h));el.style.width=o.w/d.w*100+'%';el.style.height=o.h/d.h*100+'%';renderProps()};el.onpointerup=()=>{el.onpointermove=null;renderCanvas()}}
function updateProps(){const o=current();if(!o)return;const d=dim();o.label=$('pLabel').value;o.w=Math.max(1,Math.min(d.w,+$('pW').value||1));o.h=Math.max(1,Math.min(d.h,+$('pH').value||1));o.x=Math.max(0,Math.min(d.w-o.w,+$('pX').value||0));o.y=Math.max(0,Math.min(d.h-o.h,+$('pY').value||0));o.visible=$('pVisible').checked;o.locked=$('pLocked').checked;if(o.type==='text'){o.text=$('pText').value;o.fontSize=Math.max(4,+$('pFont').value||8);o.color=$('pColor').value;o.fontWeight=+$('pWeight').value;o.align=$('pAlign').value;o.lineHeight=+$('pLine').value||1.15;o.letterSpacing=+$('pLetter').value||0;o.fontStyle=$('pItalic').checked?'italic':'normal';o.underline=$('pUnderline').checked;o.wrap=$('pWrap').checked}renderCanvas()}
['pLabel','pX','pY','pW','pH','pText','pFont','pColor','pWeight','pAlign','pLine','pLetter','pItalic','pUnderline','pWrap','pVisible','pLocked'].forEach(id=>$(id).addEventListener('input',updateProps));
document.querySelectorAll('.nudge').forEach(b=>b.onclick=()=>{const o=current();if(!o||o.locked)return;snapshot();const step=+$('nudgeStep').value||.5,d=dim();o.x=Math.max(0,Math.min(d.w-o.w,o.x+(+b.dataset.dx)*step));o.y=Math.max(0,Math.min(d.h-o.h,o.y+(+b.dataset.dy)*step));renderCanvas()});
$('layerList').onclick=e=>{const row=e.target.closest('.layer');if(!row)return;const o=state.objects.find(x=>x.id===row.dataset.id);if(e.target.closest('.toggle-visible')){snapshot();o.visible=!o.visible}else if(e.target.closest('.toggle-lock')){snapshot();o.locked=!o.locked}else selectedId=o.id;renderCanvas()};
document.querySelectorAll('.type-btn').forEach(b=>b.onclick=()=>{snapshot();state.type=b.dataset.type;state.face='front';selectedId=state.objects.find(o=>o.face==='front')?.id||null;renderCanvas()});document.querySelectorAll('.face-tabs .btn').forEach(b=>b.onclick=()=>{state.face=b.dataset.face;selectedId=state.objects.find(o=>o.face===state.face)?.id||null;renderCanvas()});
['mainColor','secondColor','accentColor'].forEach((id,i)=>$(id).oninput=()=>{state.colors[['main','second','accent'][i]]=$(id).value;renderCanvas()});
$('gridBtn').onclick=()=>{state.grid=!state.grid;renderCanvas()};$('safeBtn').onclick=()=>{state.safe=!state.safe;renderCanvas()};$('centerHBtn').onclick=()=>{const o=current();if(!o)return;snapshot();o.x=(dim().w-o.w)/2;renderCanvas()};$('centerVBtn').onclick=()=>{const o=current();if(!o)return;snapshot();o.y=(dim().h-o.h)/2;renderCanvas()};
$('frontBtn').onclick=()=>{const o=current();if(!o)return;snapshot();o.z=Math.max(...state.objects.map(x=>x.z))+1;renderCanvas()};$('backBtn').onclick=()=>{const o=current();if(!o)return;snapshot();o.z=Math.min(...state.objects.map(x=>x.z))-1;renderCanvas()};$('duplicateBtn').onclick=()=>{const o=current();if(!o)return;snapshot();const n=structuredClone(o);n.id=o.id+'_'+Date.now();n.label=o.label+' (bản sao)';n.x=Math.min(dim().w-n.w,n.x+2);n.y=Math.min(dim().h-n.h,n.y+2);state.objects.push(n);selectedId=n.id;renderCanvas()};$('deleteBtn').onclick=()=>{const o=current();if(!o||!confirm('Xóa đối tượng này?'))return;snapshot();state.objects=state.objects.filter(x=>x.id!==o.id);selectedId=faceObjects()[0]?.id||null;renderCanvas()};
$('addTextBtn').onclick=()=>{snapshot();const o=text('text_'+Date.now(),'Khối chữ mới',state.face,5,25,30,8,'Nội dung mới',8,'#10243a',400,'center');state.objects.push(o);selectedId=o.id;renderCanvas()};
$('logoUploadBtn').onclick=()=>$('logoFile').click();$('logoFile').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{snapshot();const logo=state.objects.find(o=>o.id==='logo');if(logo)logo.source=r.result;renderCanvas()};r.readAsDataURL(f)};
$('saveBtn').onclick=save;$('resetBtn').onclick=()=>{if(!confirm('Xóa mẫu hiện tại và khôi phục mặc định?'))return;snapshot();state=defaultState();selectedId=state.objects[0].id;save();renderCanvas()};$('undoBtn').onclick=()=>{if(!history.length)return;future.push(JSON.stringify(state));state=JSON.parse(history.pop());selectedId=state.objects[0]?.id||null;renderCanvas()};$('redoBtn').onclick=()=>{if(!future.length)return;history.push(JSON.stringify(state));state=JSON.parse(future.pop());selectedId=state.objects[0]?.id||null;renderCanvas()};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('undoBtn').click()}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();$('redoBtn').click()}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();const map={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]},[dx,dy]=map[e.key],o=current();if(!o||o.locked)return;const step=(+$('nudgeStep').value||.5)*(e.shiftKey?5:1),d=dim();snapshot();o.x=Math.max(0,Math.min(d.w-o.w,o.x+dx*step));o.y=Math.max(0,Math.min(d.h-o.h,o.y+dy*step));renderCanvas()}});
function showDesign(){save();$('designArea').classList.remove('hidden');$('printArea').classList.add('hidden')}
function showPrint(){save();$('designArea').classList.add('hidden');$('printArea').classList.remove('hidden');renderSelected()}
$('designModeBtn').onclick=showDesign;$('printModeBtn').onclick=showPrint;$('backDesignBtn').onclick=showDesign;
$('gradeFilter').onchange=()=>{const g=$('gradeFilter').value;[...$('classFilter').options].forEach((o,i)=>{if(i)o.hidden=!!g&&o.dataset.grade!==g});if($('classFilter').selectedOptions[0]?.hidden)$('classFilter').value=''};
async function loadStudentData(){$('loadStatus').textContent='Đang tải...';$('studentResults').innerHTML='';const p=new URLSearchParams({grade:$('gradeFilter').value,class:$('classFilter').value,q:$('searchFilter').value.trim(),photo:$('photoFilter').value,limit:'1000'});try{const res=await fetch(BASE+'student_card_students.php?'+p,{credentials:'same-origin'}),data=await res.json();if(!data.ok)throw new Error(data.message||'Lỗi');loadedStudents=data.students||[];$('loadStatus').textContent='Đã tải '+loadedStudents.length+' học sinh.';$('studentResults').innerHTML=loadedStudents.map(s=>`<label class="student-row"><input class="form-check-input print-student" type="checkbox" value="${esc(s.id)}"><img src="${esc(s.photo_url)}" onerror="this.style.visibility='hidden'"><span><strong>${esc(s.name)}</strong><small class="d-block text-muted">${esc(s.class_name)} · ${esc(s.code||'')}</small></span></label>`).join('')||'<div class="text-muted py-3">Không có học sinh phù hợp.</div>'}catch(err){$('loadStatus').textContent='Lỗi: '+err.message}}
$('loadStudents').onclick=loadStudentData;$('searchFilter').onkeydown=e=>{if(e.key==='Enter')loadStudentData()};$('studentResults').onchange=renderSelected;$('selectAll').onclick=()=>{document.querySelectorAll('.print-student').forEach(x=>x.checked=true);renderSelected()};$('clearAll').onclick=()=>{document.querySelectorAll('.print-student').forEach(x=>x.checked=false);renderSelected()};
function renderCardSet(s){return `<article class="fold-preview">${faceHtml('front',s)}<div class="fold-line"></div>${faceHtml('back',s)}</article>`}
function renderSelected(){const ids=new Set([...document.querySelectorAll('.print-student:checked')].map(x=>x.value)),rows=loadedStudents.filter(s=>ids.has(String(s.id)));$('selectedCount').textContent=rows.length;$('printPreview').innerHTML=rows.map(renderCardSet).join('');makeQr($('printPreview'))}
$('printCards').onclick=()=>{if(!document.querySelector('.print-student:checked')){alert('Hãy chọn ít nhất một học sinh.');return}renderSelected();setTimeout(()=>window.print(),150)};
renderCanvas();
</script>
</body>
</html>
